#include <M5Stack.h>
unsigned long startTime = 0;
unsigned long elapsedSeconds = 0;
bool timerRunning = false;
bool buttonAPressed = false;
bool buttonBPressed = false;

void setup() {
  M5.begin();
  M5.Lcd.setTextSize(3);
  M5.Lcd.setTextColor(WHITE, BLACK);
  M5.Lcd.clear();
  M5.Lcd.setCursor(20, 20);
  M5.Lcd.println("=== ТАЙМЕР ===");
  updateDisplay();
  M5.Lcd.setTextSize(2);
  M5.Lcd.setCursor(10, 180);
  M5.Lcd.println("A: Старт/Стоп  B: Сброс");
}

void loop() {
  M5.update();
  if (M5.BtnA.wasPressed()) {
    if (timerRunning) {
      timerRunning = false;
      elapsedSeconds += (millis() - startTime) / 1000;
    } else {
      startTime = millis();
      timerRunning = true;
    }
    updateDisplay();
  }

  if (M5.BtnB.wasPressed()) {
    timerRunning = false;
    elapsedSeconds = 0;
    updateDisplay();
  }

  if (timerRunning) {
    unsigned long currentElapsed = elapsedSeconds + (millis() - startTime) / 1000;
    displayTime(currentElapsed);
  }

  delay(100);
}

void updateDisplay() {
  unsigned long totalSeconds = elapsedSeconds;
  if (timerRunning) {
    totalSeconds += (millis() - startTime) / 1000;
  }
  displayTime(totalSeconds);
}
void displayTime(unsigned long totalSeconds) {
  int hours = totalSeconds / 3600;
  int minutes = (totalSeconds % 3600) / 60;
  int seconds = totalSeconds % 60;
  M5.Lcd.fillRect(10, 60, 300, 80, BLACK);
  M5.Lcd.setTextSize(4);
  M5.Lcd.setCursor(30, 60);

  char timeStr[10];
  sprintf(timeStr, "%02d:%02d:%02d", hours, minutes, seconds);
  M5.Lcd.println(timeStr);
  M5.Lcd.setTextSize(2);
  M5.Lcd.setCursor(10, 140);
  M5.Lcd.fillRect(10, 140, 300, 30, BLACK);
  if (timerRunning) {
    M5.Lcd.println(">> ТАЙМЕР ЗАПУЩЕН <<");
  } else {
    M5.Lcd.println("   ТАЙМЕР ОСТАНОВЛЕН   ");
  }
}
